<?php namespace App\Models;use Illuminate\Database\Eloquent\Factories\HasFactory;use Illuminate\Database\Eloquent\Model;class Product extends Model{use HasFactory;protected $fillable=['category_id','name','slug','sku','description','price','discount_price','stock','image','featured','status','brand','tags','specifications','seo_title','seo_description','published_at'];protected $casts=['price'=>'decimal:2','discount_price'=>'decimal:2','featured'=>'boolean','status'=>'boolean','tags'=>'array','specifications'=>'array','published_at'=>'datetime'];public function category(){return $this->belongsTo(Category::class);}public function reviews(){return $this->hasMany(Review::class);}public function wishlists(){return $this->hasMany(Wishlist::class);}public function variants(){return $this->hasMany(ProductVariant::class);}public function images(){return $this->hasMany(ProductImage::class)->orderBy('sort_order');}public function questions(){return $this->hasMany(ProductQuestion::class);}public function vendors(){return $this->belongsToMany(Vendor::class,'vendor_products');}public function getSalePriceAttribute():float{return (float)($this->discount_price??$this->price);}public function getAverageRatingAttribute():float{return round((float)$this->reviews()->where('approved',true)->avg('rating'),1);}}
